-- ROLLBACK for prisma/data-sql/tariff-calculator/20261013-2026-revision-21-hts-lines-sync-ch91-statistical-suffixes.sql (hts_codes lines → HTS 2026 Revision 21). NOT for the repo: it holds a full copy of
-- the 0 deleted hts_codes rows and their 0 hts_code_candidate_codes links.
-- Run only after the sync was committed: deletes the rows it inserted, re-inserts the deleted rows (original
-- ids and columns) and links, restores sort_order / parent_id / indent / description / updated_at of every
-- pre-sync row of the 1 affected chapters, then checks each chapter's ids + order equal the pre-sync
-- snapshot (fingerprints: 91=a74281aa).
-- Links are only restorable while their tariff_candidate_codes rows still exist.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Delete the rows the sync inserted (numbered by hts_number; headers by chapter + post-sync sort_order + indent + description)
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE tmp_rb_inserted (chapter_number INT NOT NULL, hts_number TEXT, sort_order INT NOT NULL, indent INT NOT NULL, description TEXT NOT NULL) ON COMMIT DROP;
WITH deleted AS (
  DELETE FROM hts_codes h
   USING tmp_rb_inserted i, tariff_chapters c
   WHERE c.space_id = 'koala_gains' AND c.number = i.chapter_number AND h.space_id = 'koala_gains' AND h.chapter_id = c.id
     AND ((i.hts_number IS NOT NULL AND h.hts_number = i.hts_number)
       OR (i.hts_number IS NULL AND h.hts_number IS NULL AND h.sort_order = i.sort_order AND h.indent = i.indent AND h.description = i.description))
  RETURNING h.id
)
SELECT 'inserted rows removed (expected 328)' AS step, count(*) AS rows FROM deleted;

-- ---------------------------------------------------------------------------
-- 2. Re-insert the 0 deleted rows with all their original columns
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 3. Re-insert their 0 hts_code_candidate_codes links
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 4. Restore sort_order / parent_id / indent / description / updated_at of all 314 pre-sync rows of the affected chapters
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE tmp_rb_restore (id TEXT PRIMARY KEY, sort_order INT NOT NULL, parent_id TEXT, indent INT NOT NULL, description TEXT NOT NULL, updated_at TIMESTAMP(3) NOT NULL) ON COMMIT DROP;
UPDATE hts_codes h
   SET sort_order = r.sort_order, parent_id = r.parent_id, indent = r.indent, description = r.description, updated_at = r.updated_at
  FROM tmp_rb_restore r
 WHERE h.id = r.id;

-- ---------------------------------------------------------------------------
-- 5. Check: every affected chapter is back to its pre-sync rows (same ids in the same order)
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE tmp_rb_snapshot (chapter_number INT PRIMARY KEY, row_count INT NOT NULL, ids_md5 TEXT NOT NULL) ON COMMIT DROP;
DO $$ DECLARE drifted TEXT; BEGIN
  SELECT string_agg(s.chapter_number::text, ', ' ORDER BY s.chapter_number) INTO drifted
    FROM tmp_rb_snapshot s
    JOIN tariff_chapters c ON c.space_id = 'koala_gains' AND c.number = s.chapter_number
    LEFT JOIN LATERAL (SELECT count(*)::int AS n, md5(coalesce(string_agg(h.id, ',' ORDER BY h.sort_order, h.id COLLATE "C"), '')) AS m
                         FROM hts_codes h WHERE h.chapter_id = c.id AND h.space_id = 'koala_gains') cur ON true
   WHERE cur.n <> s.row_count OR cur.m <> s.ids_md5;
  IF drifted IS NOT NULL THEN RAISE EXCEPTION 'rollback did not restore chapter(s) %', drifted; END IF; END $$;

COMMIT;
